"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

type AttachmentListProps = React.ComponentProps<"ul"> & {
  /**
   * reverse: the extension is reversed out of an ink block that prints across it as the file arrives.
   * enclosure: the files written as a letter's enclosure line, "Encl. (2)", run on in one sentence.
   */
  variant?: "default" | "reverse" | "enclosure"
}

/** The list the files sit in. */
function AttachmentList({ variant = "default", className, children, ...props }: AttachmentListProps) {
  return (
    <ul
      data-slot="attachment-list"
      data-variant={variant === "default" ? undefined : variant}
      data-count={variant === "enclosure" ? React.Children.count(children) : undefined}
      aria-label={variant === "enclosure" ? "Enclosures" : undefined}
      className={cn("db-attachments", className)}
      {...props}
    >
      {children}
    </ul>
  )
}

type AttachmentProps = Omit<React.ComponentProps<"li">, "children"> & {
  name: string
  /** The size, as it should read: "2.4 MB". Set in tabular figures. */
  size?: string
  /** Says what is happening or what went wrong, in place of the size: "Checking", "The connection dropped." */
  status?: string
  state?: "idle" | "uploading" | "processing" | "done" | "error"
  /** How far an upload has got, 0 to 1. The ring counts it in. */
  progress?: number
  /** Shows a Remove button, labelled with the file's name. */
  onRemove?: () => void
}

/** A file: its extension is its picture, a ring counts it in and fills to a dot when it's safe. */
function Attachment({ name, size, status, state = "done", progress, onRemove, className, style, ...props }: AttachmentProps) {
  const ext = name.includes(".") ? name.slice(name.lastIndexOf(".") + 1) : ""
  return (
    <li
      data-slot="attachment"
      data-state={state}
      className={cn("db-attach", className)}
      style={progress === undefined ? style : ({ "--p": progress, ...style } as React.CSSProperties)}
      {...props}
    >
      <span className="db-attach-ext" data-ext={ext} aria-hidden="true">{ext}</span>
      <span className="db-attach-body">
        <span className="db-attach-name">{name}</span>
        <span className="db-attach-meta">{status ?? size}</span>
      </span>
      <svg className="db-attach-ring" viewBox="0 0 22 22" aria-hidden="true">
        <circle className="db-attach-track" cx="11" cy="11" r="9.5" />
        <circle className="db-attach-arc" cx="11" cy="11" r="9.5" pathLength="1" />
        <circle className="db-attach-fill" cx="11" cy="11" />
      </svg>
      {onRemove ? (
        <Button variant="bracket" aria-label={`Remove ${name}`} onClick={onRemove}>
          Remove
        </Button>
      ) : null}
    </li>
  )
}

export { Attachment, AttachmentList, type AttachmentProps, type AttachmentListProps }

@layer components {
  /* ── db-attach ── a file: its extension is its picture; a ring counts it in */
  .db-attachments { list-style: none; margin: 0; padding: 0; border-top: var(--db-hairline) solid var(--db-rule); }
  .db-attach { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr) auto auto; align-items: center; column-gap: var(--db-space-4); padding-block: var(--db-space-3); border-bottom: var(--db-hairline) solid var(--db-rule); }
  .db-attach-ext { font-size: var(--db-mf); line-height: 1; font-weight: 200; font-stretch: 125%; color: var(--db-ink); text-transform: lowercase; }
  .db-attach-body { display: grid; min-width: 0; }
  .db-attach-name { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.3; color: var(--db-ink); }
  .db-attach-meta { font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-attach-ring { width: 22px; height: 22px; overflow: visible; rotate: -90deg; }
  .db-attach-ring circle { fill: none; stroke-width: 1.5; }
  .db-attach-track { stroke: var(--db-rule); transition: stroke-opacity var(--db-moderato) var(--db-breath) var(--db-moderato); }
  .db-attach-arc { stroke: var(--db-ink); stroke-dasharray: 1; stroke-dashoffset: calc(1 - var(--p, 0)); transition: stroke-dashoffset var(--db-moderato) var(--db-breath), stroke var(--db-allegro), stroke-opacity var(--db-moderato) var(--db-breath) var(--db-moderato); }
  .db-attach-ring .db-attach-fill { fill: var(--db-ink); stroke: none; r: 0; transition: r var(--db-moderato) var(--db-spiccato) var(--db-moderato); }
  .db-attach[data-state="processing"] .db-attach-arc { --p: 1; stroke: var(--db-pencil); }
  .db-attach[data-state="done"] .db-attach-arc { --p: 1; }
  /* Safe, the ring closes and gives way to a full stop: a ring round a dot would read as a chosen radio. */
  .db-attach[data-state="done"] :is(.db-attach-track, .db-attach-arc) { stroke-opacity: 0; }
  .db-attach[data-state="done"] .db-attach-fill { r: calc(var(--db-dot) / 2); }
  .db-attach[data-state="error"] .db-attach-arc { stroke: var(--db-signal); }
  .db-attach[data-state="error"] .db-attach-meta { color: var(--db-signal); }
  .db-attach > .db-btn { font-size: var(--db-pp); }
  @media (max-width: 30rem) {
    .db-attach { grid-template-columns: 3.4rem minmax(0, 1fr) auto auto; }
    .db-attach-ext { font-size: var(--db-mp); }
    /* Narrow, Remove steps down under the name, so the name keeps the width. */
    .db-attach > .db-btn { grid-column: 2 / -1; justify-self: start; }
  }

  /* ── reverse ── after "the uncreative": the extension reversed out of an ink block. The block prints across the
     letters as the file arrives (--p), so each letter turns from ink on paper to paper on ink. Checking, the block
     is pencil; safe, it is ink; failed, it stops in crimson where the connection dropped. */
  .db-attachments[data-variant="reverse"] .db-attach { grid-template-columns: 4.5rem minmax(0, 1fr) auto; }
  .db-attachments[data-variant="reverse"] .db-attach-ring { display: none; }
  .db-attachments[data-variant="reverse"] .db-attach-ext {
    position: relative; justify-self: start; padding: 0.06em 0.12em 0.12em;
    font-weight: 700; font-stretch: 100%; letter-spacing: -0.04em;
  }
  .db-attachments[data-variant="reverse"] .db-attach-ext::after {
    content: attr(data-ext) / ""; position: absolute; inset: 0; padding: inherit; background: var(--db-ink); color: var(--db-paper);
    clip-path: inset(0 calc((1 - var(--p, 0)) * 100%) 0 0); transition: clip-path var(--db-moderato) var(--db-breath), background-color var(--db-moderato);
  }
  :is([dir="rtl"], [dir="rtl"] *) .db-attachments[data-variant="reverse"] .db-attach-ext::after { clip-path: inset(0 0 0 calc((1 - var(--p, 0)) * 100%)); }
  .db-attachments[data-variant="reverse"] .db-attach:is([data-state="processing"], [data-state="done"]) { --p: 1; }
  .db-attachments[data-variant="reverse"] .db-attach[data-state="processing"] .db-attach-ext::after { background: var(--db-pencil); }
  .db-attachments[data-variant="reverse"] .db-attach[data-state="error"] .db-attach-ext::after { background: var(--db-signal); }
  @media (max-width: 30rem) {
    .db-attachments[data-variant="reverse"] .db-attach { grid-template-columns: 3.4rem minmax(0, 1fr); }
  }
  @media (forced-colors: active) {
    .db-attachments[data-variant="reverse"] .db-attach-ext::after { forced-color-adjust: none; background: CanvasText; color: Canvas; }
  }

  /* ── enclosure ── the letter's enclosure line: "Encl. (2)", then each file run on in one sentence, the name yours in
     italic and its size in parentheses, a semicolon between and a full stop at the end. The ring stays only while a
     file is on its way. */
  .db-attachments[data-variant="enclosure"] { border-top: 0; font-size: var(--db-p); line-height: var(--db-p-lh); color: var(--db-pencil); }
  .db-attachments[data-variant="enclosure"]::before { content: "Encl.\00a0(" attr(data-count) ")\00a0\00a0" / ""; color: var(--db-graphite); }
  .db-attachments[data-variant="enclosure"] > .db-attach { display: inline; padding: 0; border: 0; }
  .db-attachments[data-variant="enclosure"] > .db-attach:not(:last-child)::after { content: ";" / ""; margin-inline-end: 0.3em; }
  .db-attachments[data-variant="enclosure"] > .db-attach:last-child::after { content: "." / ""; }
  .db-attachments[data-variant="enclosure"] :is(.db-attach-ext, .db-attach[data-state="done"] .db-attach-ring) { display: none; }
  .db-attachments[data-variant="enclosure"] :is(.db-attach-body, .db-attach-name, .db-attach-meta) { display: inline; font-size: inherit; line-height: inherit; }
  .db-attachments[data-variant="enclosure"] .db-attach-name { white-space: normal; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; }
  .db-attachments[data-variant="enclosure"] .db-attach-meta { white-space: nowrap; }
  .db-attachments[data-variant="enclosure"] .db-attach-meta::before { content: "\00a0(" / ""; }
  .db-attachments[data-variant="enclosure"] .db-attach-meta::after { content: ")" / ""; }
  .db-attachments[data-variant="enclosure"] .db-attach-ring { display: inline; width: 0.7em; height: 0.7em; margin-inline-start: 0.35em; vertical-align: -0.05em; }
  .db-attachments[data-variant="enclosure"] .db-attach > .db-btn { display: inline-flex; margin-inline-start: 0.35em; vertical-align: baseline; }
}
